+    @Reflect
+    static int continueFromTryWhileTWR(int value) {
+        int i = 0;
+        try {
+            while (i++ < value) {
+                try (var resource = Stream.empty()) {
+                    continue;
+                }
+            }
+        } finally {
+            i++;
+        }
+        return i;
+    }
+
+    @Reflect
+    static int continueFromSynchronizedWhileTWR(int value) {
+        int i = 0;
+        synchronized (TestBytecode.class) {
+            while (i++ < value) {
+                try (var resource = Stream.empty()) {
+                    continue;
+                }
+            }
+        }
+        return i;
+    }
